import 'dart:convert';
import 'dart:io';

import 'package:content_build/content_build.dart';
import 'package:test/test.dart';

/// The fixture generated by this tool from the downloaded canon. Re-generate
/// with `--fixture-out`, never edit by hand.
const String fixturePath =
    '../../packages/testing/fixtures/content_p582_583.json';

const String configPath = 'config/prototype.json';

/// The whole-Quran text fixture (ADR 0004), generated by this tool.
const String textFixturePath =
    '../../packages/testing/fixtures/quran_text.json';

void main() {
  late Map<String, Object?> fixture;
  late List<Map<String, Object?>> words;
  late List<Map<String, Object?>> ayahs;

  List<Map<String, Object?>> rows(String table) =>
      (fixture[table]! as List<Object?>).cast<Map<String, Object?>>();
  // Every table key is written by ContentData.toJson.

  setUpAll(() {
    fixture = jsonDecode(File(fixturePath).readAsStringSync())
        as Map<String, Object?>;
    words = rows('words');
    ayahs = rows('ayahs');
  });

  test('was built from the pinned canon with a license (ПР-02, ПР-04)', () {
    final config = BuildConfig.fromJson(File(configPath).readAsStringSync());
    final version = (fixture['contentVersion']! as Map<String, Object?>)
        .cast<String, String>(); // Always written.
    expect(version['canonSha256'], config.expectedCanonSha256);
    expect(version['textLicense'], config.text.license);
    expect(version['textNotice'], contains('Tanzil'));
  });

  test('surah 78 is complete: 40 ayahs, word counts match rows', () {
    final surah78 = ayahs.where((a) => a['surah'] == 78).toList();
    expect(surah78, hasLength(40));
    for (final ayah in ayahs) {
      final count = words
          .where(
            (w) => w['surah'] == ayah['surah'] && w['ayah'] == ayah['ayah'],
          )
          .length;
      expect(
        count,
        ayah['wordCount'],
        reason: '${ayah['surah']}:${ayah['ayah']}',
      );
    }
  });

  test('every word has a page, a line and a glyph code (ПР-04)', () {
    for (final w in words) {
      final where = '${w['surah']}:${w['ayah']}:${w['position']}';
      expect([582, 583], contains(w['page']), reason: where);
      expect(w['line'], inInclusiveRange(1, 15), reason: where);
      expect(w['glyphCode'], isA<String>(), reason: where);
      expect(w['glyphCode'], isNotEmpty, reason: where);
    }
  });

  test('word indexes are contiguous and words are canon slices', () {
    final indexes = [for (final w in words) w['wordIndex']! as int];
    for (var i = 1; i < indexes.length; i++) {
      expect(indexes[i], indexes[i - 1] + 1);
    }
    for (final ayah in ayahs) {
      final texts = [
        for (final w in words)
          if (w['surah'] == ayah['surah'] && w['ayah'] == ayah['ayah'])
            w['textUthmani']! as String,
      ];
      expect(segmentAyah(texts.join(tanzilTokenSeparator)), texts);
    }
  });

  group('whole-Quran text fixture (ADR 0004)', () {
    late Map<String, Object?> text;
    late List<List<Object?>> textAyahs;

    setUpAll(() {
      text = jsonDecode(File(textFixturePath).readAsStringSync())
          as Map<String, Object?>;
      textAyahs = (text['ayahs']! as List<Object?>).cast<List<Object?>>();
      // Every key is written by QuranTextData.toJson.
    });

    test('is the pinned canon: checksum of the words joined back', () {
      final config = BuildConfig.fromJson(File(configPath).readAsStringSync());
      final lines = StringBuffer();
      for (final a in textAyahs) {
        final words = (a[2]! as List<Object?>).cast<String>();
        lines.write('${a[0]}|${a[1]}|${words.join(tanzilTokenSeparator)}\n');
      }
      expect(
        bytesChecksum(utf8.encode(lines.toString())),
        config.expectedCanonSha256,
      );
      final version = (text['contentVersion']! as Map<String, Object?>)
          .cast<String, String>(); // Always written.
      expect(version['canonSha256'], config.expectedCanonSha256);
      expect(version['textLicense'], config.text.license);
      expect(version['textNotice'], contains('Tanzil'));
      expect(version.keys, isNot(contains('layoutLicense')));
    });

    test('holds the whole Quran: 114 surahs, 6236 ayahs, 77 433 words', () {
      expect(text['format'], textJsonFormat);
      expect(text['kind'], 'text');
      final surahs = (text['surahs']! as List<Object?>)
          .cast<Map<String, Object?>>(); // Always written.
      expect(surahs, hasLength(114));
      expect(textAyahs, hasLength(6236));
      final words = textAyahs.fold<int>(
        0,
        (n, a) => n + (a[2]! as List<Object?>).length,
      );
      expect(words, 77433);
      for (final s in surahs) {
        final count = textAyahs.where((a) => a[0] == s['number']).length;
        expect(count, s['ayahCount'], reason: 'surah ${s['number']}');
      }
    });

    test('agrees with the pages fixture on every word', () {
      final firstIndex = <(int, int), int>{};
      var next = 1;
      for (final a in textAyahs) {
        firstIndex[(a[0]! as int, a[1]! as int)] = next;
        next += (a[2]! as List<Object?>).length;
      }
      for (final w in words) {
        final key = (w['surah']! as int, w['ayah']! as int);
        final ayah = textAyahs.firstWhere((a) => (a[0], a[1]) == key);
        final position = w['position']! as int;
        expect(
          (ayah[2]! as List<Object?>)[position - 1],
          w['textUthmani'],
          reason: '$key:$position',
        );
        expect(firstIndex[key]! + position - 1, w['wordIndex']);
      } // Keys are read from the fixtures, always present.
    });
  });
}
